1: /**
2:  * scripts/generate-icons.js
3:  * Pure Node.js high-fidelity PNG icon generator for Cinejoy webOS TV
4:  * Zero external npm dependencies. Uses native zlib and Buffer.
5:  */
6: 
7: const fs = require('fs');
8: const path = require('path');
9: const zlib = require('zlib');
10: 
11: // Precomputed CRC-32 table for PNG chunk checksumming
12: const crcTable = new Uint32Array(256);
13: for (let n = 0; n < 256; n++) {
14:   let c = n;
15:   for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
16:   crcTable[n] = c;
17: }
18: 
19: function crc32(buf) {
20:   let crc = 0xFFFFFFFF;
21:   for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ crcTable[(crc ^ buf[i]) & 0xFF];
22:   return (crc ^ 0xFFFFFFFF) >>> 0;
23: }
24: 
25: function createPng(width, height, sampleFn) {
26:   const scale = width / 80;
27:   const subSteps = 4; // 4x4 supersampling for anti-aliased vector edges
28:   const totalSamples = subSteps * subSteps;
29: 
30:   const rowStride = 1 + width * 4;
31:   const raw = Buffer.alloc(height * rowStride);
32: 
33:   for (let y = 0; y < height; y++) {
34:     const rowOffset = y * rowStride;
35:     raw[rowOffset] = 0; // Filter method: 0 (None)
36:     for (let x = 0; x < width; x++) {
37:       let rSum = 0, gSum = 0, bSum = 0, aSum = 0;
38:       for (let sy = 0; sy < subSteps; sy++) {
39:         for (let sx = 0; sx < subSteps; sx++) {
40:           const subX = x + (sx + 0.5) / subSteps;
41:           const subY = y + (sy + 0.5) / subSteps;
42:           const [sr, sg, sb, sa] = sampleFn(subX, subY, scale);
43:           rSum += (sr * sa) / 255;
44:           gSum += (sg * sa) / 255;
45:           bSum += (sb * sa) / 255;
46:           aSum += sa;
47:         }
48:       }
49:       const avgA = aSum / totalSamples;
50:       const avgR = avgA > 0 ? (rSum / totalSamples) * (255 / avgA) : 0;
51:       const avgG = avgA > 0 ? (gSum / totalSamples) * (255 / avgA) : 0;
52:       const avgB = avgA > 0 ? (bSum / totalSamples) * (255 / avgA) : 0;
53: 
54:       const pxOffset = rowOffset + 1 + x * 4;
55:       raw[pxOffset] = Math.round(avgR);
56:       raw[pxOffset + 1] = Math.round(avgG);
57:       raw[pxOffset + 2] = Math.round(avgB);
58:       raw[pxOffset + 3] = Math.round(avgA);
59:     }
60:   }
61: 
62:   const idatData = zlib.deflateSync(raw, { level: 9 });
63: 
64:   function makeChunk(type, data) {
65:     const typeBuf = Buffer.from(type, 'ascii');
66:     const lenBuf = Buffer.alloc(4);
67:     lenBuf.writeUInt32BE(data.length, 0);
68:     const body = Buffer.concat([typeBuf, data]);
69:     const crcBuf = Buffer.alloc(4);
70:     crcBuf.writeUInt32BE(crc32(body), 0);
71:     return Buffer.concat([lenBuf, body, crcBuf]);
72:   }
73: 
74:   const ihdr = Buffer.alloc(13);
75:   ihdr.writeUInt32BE(width, 0);
76:   ihdr.writeUInt32BE(height, 4);
77:   ihdr[8] = 8; // 8-bit depth
78:   ihdr[9] = 6; // Color type: RGBA
79:   ihdr[10] = 0; // Deflate compression
80:   ihdr[11] = 0; // Filter method
81:   ihdr[12] = 0; // Non-interlaced
82: 
83:   const sig = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
84:   const ihdrChunk = makeChunk('IHDR', ihdr);
85:   const idatChunk = makeChunk('IDAT', idatData);
86:   const iendChunk = makeChunk('IEND', Buffer.alloc(0));
87: 
88:   return Buffer.concat([sig, ihdrChunk, idatChunk, iendChunk]);
