91: function sampleCinejoyIcon(x, y, scale) {
92:   const BG_COLOR = [4, 18, 11, 255];       // #04120B
93:   const ACCENT_LIME = [149, 255, 80, 255]; // #95FF50
94:   const DOT_WHITE = [255, 255, 255, 255];  // #FFFFFF
95: 
96:   const pad = 4 * scale;
97:   const rw = 72 * scale;
98:   const rh = 72 * scale;
99:   const radius = 16 * scale;
100:   const borderWidth = 2.5 * scale;
101: 
102:   // Signed distance function for rounded rectangle
103:   function inRoundedRect(px, py, rx, ry, w, h, r) {
104:     if (px < rx || px > rx + w || py < ry || py > ry + h) return false;
105:     const innerLeft = rx + r;
106:     const innerRight = rx + w - r;
107:     const innerTop = ry + r;
108:     const innerBottom = ry + h - r;
109:     if (px >= innerLeft && px <= innerRight) return true;
110:     if (py >= innerTop && py <= innerBottom) return true;
111:     let dx = 0, dy = 0;
112:     if (px < innerLeft) dx = px - innerLeft;
113:     else if (px > innerRight) dx = px - innerRight;
114:     if (py < innerTop) dy = py - innerTop;
115:     else if (py > innerBottom) dy = py - innerBottom;
116:     return (dx * dx + dy * dy) <= (r * r);
117:   }
118: 
119:   // Point in triangle test
120:   function inTriangle(px, py, [x1, y1], [x2, y2], [x3, y3]) {
121:     const d1 = (px - x2) * (y1 - y2) - (x1 - x2) * (py - y2);
122:     const d2 = (px - x3) * (y2 - y3) - (x2 - x3) * (py - y3);
123:     const d3 = (px - x1) * (y3 - y1) - (x3 - x1) * (py - y1);
124:     const hasNeg = (d1 < 0) || (d2 < 0) || (d3 < 0);
125:     const hasPos = (d1 > 0) || (d2 > 0) || (d3 > 0);
126:     return !(hasNeg && hasPos);
127:   }
128: 
129:   // 1. Outside outer rounded container
130:   if (!inRoundedRect(x, y, pad, pad, rw, rh, radius)) {
131:     return [0, 0, 0, 0];
132:   }
133: 
134:   // 2. On rounded border
135:   const onInner = inRoundedRect(x, y, pad + borderWidth, pad + borderWidth, rw - 2 * borderWidth, rh - 2 * borderWidth, Math.max(0, radius - borderWidth));
136:   if (!onInner) {
137:     return ACCENT_LIME;
138:   }
139: 
140:   // 3. Top-right white accent dot
141:   const dotX = 58 * scale;
142:   const dotY = 22 * scale;
143:   const dotR = 4 * scale;
144:   if ((x - dotX) * (x - dotX) + (y - dotY) * (y - dotY) <= dotR * dotR) {
145:     return DOT_WHITE;
146:   }
147: 
148:   // 4. Directional Play Glyph
149:   const p1 = [28 * scale, 23 * scale];
150:   const p2 = [28 * scale, 57 * scale];
151:   const p3 = [58 * scale, 40 * scale];
152:   if (inTriangle(x, y, p1, p2, p3)) {
153:     return ACCENT_LIME;
154:   }
155: 
156:   // 5. Container background
157:   return BG_COLOR;
158: }
159: 
